//! A supervised value/policy network for Meridian, trained on every game from
//! the site (meridian-games.zip) and exported to pure Rust for WebAssembly.
//!
//! - [`nn::eval`] evaluates a position: a value in `tanh(final margin / 1500)`
//!   space (Blue's perspective, like the site's evaluations) and the best moves
//!   according to a 17,328-way policy head over move IDs.
//! - [`nn::weights`] holds the trained parameters as raw bytes, generated by
//!   `/tmp/opencode/nn-train/export_weights.py`. Do not edit by hand.
//! - `nnbench` (src/bin) benchmarks the forward pass and checks the exported
//!   net against the training pipeline; see `docs/meridian/NN_PLAN.md`.
//!
//! The network is 8MB-limited-upload sized (~100k parameters, ~400KB of weights)
//! and inference is pure, allocation-light Rust that runs under `wasm32-wasip1`.

pub mod nn;
pub mod weights;

pub use nn::{BOARD, Eval, IN_PLANES, MARGIN_SCALE, POINTS, eval, eval_logits, eval_value, input_planes, top_moves};
